import XCTest

final class FeedTapUITests: XCTestCase {
    func testOpenFeedsTab() {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        let feeds = app.staticTexts.matching(NSPredicate(format: "label CONTAINS 'Feeds'")).firstMatch
        if feeds.waitForExistence(timeout: 5) {
            feeds.tap()
        } else {
            app.coordinate(withNormalizedOffset: CGVector(dx: 0.73, dy: 0.15)).tap()
        }
    }
}
